CREATE OR REPLACE FUNCTION public.task_pick_role(_role text) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT a.user_id FROM public.user_role_assignments a JOIN public.roles r ON r.code=a.role AND r.is_active WHERE a.role=_role AND a.is_active AND public.task_staff_active(a.user_id) ORDER BY a.user_id LIMIT 1 $$;
CREATE OR REPLACE FUNCTION public._task_upsert(_key text,_title text,_type text,_user uuid,_due timestamptz,_entity text,_id uuid,_visibility text DEFAULT 'operational') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.tasks;oldrow jsonb;BEGIN SELECT * INTO t FROM public.tasks WHERE source_key=_key FOR UPDATE;IF FOUND THEN IF t.status='open' AND (t.due_at IS DISTINCT FROM _due OR t.assignee_user_id IS DISTINCT FROM _user) THEN oldrow:=to_jsonb(t);UPDATE public.tasks SET due_at=_due,assignee_user_id=_user,updated_at=now() WHERE id=t.id;PERFORM public._safety_audit('AUTO_TASK_UPDATED','tasks',t.id::text,oldrow,(SELECT to_jsonb(x) FROM public.tasks x WHERE id=t.id),'تحديث مصدر المهمة');END IF;RETURN t.id;END IF;INSERT INTO public.tasks(title,type,assignee_user_id,due_at,entity_type,entity_id,source_key,visibility,created_by) VALUES(_title,_type,_user,_due,_entity,_id,_key,_visibility,auth.uid()) ON CONFLICT(source_key) DO NOTHING RETURNING * INTO t;IF t.id IS NOT NULL THEN PERFORM public._safety_audit('AUTO_TASK_CREATED','tasks',t.id::text,NULL,to_jsonb(t),'مهمة من مصدر موثق');INSERT INTO public.task_generation_state(source_key,task_id) VALUES(_key,t.id) ON CONFLICT DO NOTHING;END IF;RETURN t.id;END $$;
CREATE OR REPLACE FUNCTION public.task_notification_trigger() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.assignee_user_id IS NOT NULL AND NEW.status='open' THEN INSERT INTO public.user_notifications(user_id,task_id,title) VALUES(NEW.assignee_user_id,NEW.id,NEW.title) ON CONFLICT DO NOTHING;IF (SELECT task_telegram_enabled FROM public.app_settings WHERE id=1) THEN INSERT INTO public.notification_outbox(user_id,task_id,kind,source_key) VALUES(NEW.assignee_user_id,NEW.id,'task',NEW.id::text||':'||NEW.assignee_user_id::text) ON CONFLICT DO NOTHING;END IF;END IF;RETURN NEW;END $$;
CREATE OR REPLACE TRIGGER task_notification AFTER INSERT OR UPDATE ON public.tasks FOR EACH ROW EXECUTE FUNCTION public.task_notification_trigger();
CREATE OR REPLACE FUNCTION public.generate_time_tasks() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.app_settings;b record;o record;c record;i record;owner uuid;k uuid;cnt integer:=0;today date:=(now() AT TIME ZONE 'Asia/Riyadh')::date;t public.tasks;remaining numeric;BEGIN IF auth.role()<>'service_role' AND current_user<>'postgres' AND NOT public.has_permission('tasks.manage','edit') THEN RAISE EXCEPTION 'توليد المهام غير مسموح';END IF;PERFORM pg_advisory_xact_lock(60412026,10);SELECT * INTO s FROM public.app_settings WHERE id=1;
FOR b IN SELECT * FROM public.bookings WHERE archived_at IS NULL AND status='pending' LOOP SELECT owner_user_id INTO owner FROM public.opportunities WHERE booking_id=b.id AND outcome IS NULL ORDER BY created_at DESC LIMIT 1;IF NOT public.task_staff_active(owner) THEN owner:=public.task_pick_role('leasing_manager');END IF;k:=public._task_upsert('booking-contact:'||b.id,'تواصل مع العميل','booking_contact',owner,b.created_at+make_interval(hours=>s.task_response_hours),'booking',b.id);cnt:=cnt+1;IF b.expires_at IS NOT NULL AND b.expires_at<=now()+interval '24 hours' AND b.expires_at>now() THEN PERFORM public._task_upsert('hold-review:'||b.id,'مراجعة الحجز قبل انتهائه','hold_review',owner,b.expires_at,'booking',b.id);END IF;END LOOP;
FOR o IN SELECT * FROM public.opportunities WHERE outcome IS NULL AND stage<>'won' AND (next_action_at IS NULL OR next_action_at<=now()) LOOP owner:=o.owner_user_id;IF NOT public.task_staff_active(owner) THEN owner:=public.task_pick_role('leasing_manager');END IF;PERFORM public._task_upsert('opportunity-followup:'||o.id||':'||coalesce(o.next_action_at::text,'missing'),'متابعة الفرصة','opportunity_followup',owner,coalesce(o.next_action_at,o.created_at+make_interval(hours=>s.task_response_hours)),'opportunity',o.id);END LOOP;
FOR i IN SELECT x.*,c.party_id FROM public.installments x JOIN public.contracts c ON c.id=x.contract_id WHERE c.status='active' AND NOT c.needs_review AND x.status<>'waived' AND x.due_date<=today+s.installment_alert_days LOOP SELECT i.amount_incl_vat-coalesce(sum(a.amount_incl_vat) FILTER(WHERE r.status='verified' AND r.reverses_id IS NULL AND NOT EXISTS(SELECT 1 FROM public.receipts rev WHERE rev.reverses_id=r.id)),0) INTO remaining FROM public.receipt_allocations a JOIN public.receipts r ON r.id=a.receipt_id WHERE a.installment_id=i.id;IF remaining>0 THEN PERFORM public._task_upsert('installment-due:'||i.id,'متابعة استحقاق القسط','installment_due',public.task_pick_role('accountant'),i.due_date::timestamp AT TIME ZONE 'Asia/Riyadh','installment',i.id,'financial');IF public.metrics_is_overdue(i.due_date,today,s.grace_days) THEN PERFORM public._task_upsert('installment-escalation:'||i.id,'تصعيد متابعة الاستحقاق','installment_escalation',public.task_pick_role('leasing_manager'),now(),'contract',i.contract_id,'escalation');END IF;END IF;END LOOP;
FOR c IN SELECT * FROM public.contracts WHERE status='active' AND NOT needs_review AND end_date IS NOT NULL LOOP IF (c.end_date-make_interval(months=>s.contract_alert_months))::date<=today THEN PERFORM public._task_upsert('renewal-month:'||c.id||':'||c.end_date,'متابعة تجديد العقد — الشهر','contract_renewal',public.task_pick_role('leasing_manager'),c.end_date::timestamp AT TIME ZONE 'Asia/Riyadh','contract',c.id);END IF;IF c.end_date-s.contract_second_alert_days<=today THEN PERFORM public._task_upsert('renewal-week:'||c.id||':'||c.end_date,'متابعة تجديد العقد — الأسبوع','contract_renewal',public.task_pick_role('leasing_manager'),c.end_date::timestamp AT TIME ZONE 'Asia/Riyadh','contract',c.id);END IF;END LOOP;
FOR t IN SELECT * FROM public.tasks WHERE status='open' AND source_key IS NOT NULL LOOP IF (t.type IN('booking_contact','hold_review') AND NOT EXISTS(SELECT 1 FROM public.bookings WHERE id=t.entity_id AND status='pending' AND archived_at IS NULL)) OR (t.type='opportunity_followup' AND NOT EXISTS(SELECT 1 FROM public.opportunities WHERE id=t.entity_id AND outcome IS NULL AND stage<>'won' AND (next_action_at IS NULL OR next_action_at<=now()) AND t.source_key='opportunity-followup:'||id||':'||coalesce(next_action_at::text,'missing'))) OR (t.type='contract_renewal' AND NOT EXISTS(SELECT 1 FROM public.contracts WHERE id=t.entity_id AND status='active' AND t.source_key LIKE '%:'||end_date::text)) OR (t.type='installment_due' AND EXISTS(SELECT 1 FROM public.installments x WHERE x.id=t.entity_id AND (x.status IN('paid','waived') OR NOT EXISTS(SELECT 1 FROM public.contracts WHERE id=x.contract_id AND status='active')))) THEN UPDATE public.tasks SET status='cancelled',completed_at=now(),outcome_note='انتهى سبب المتابعة أو تغير مصدرها',updated_at=now() WHERE id=t.id;PERFORM public._safety_audit('AUTO_TASK_RESOLVED','tasks',t.id::text,to_jsonb(t),(SELECT to_jsonb(x) FROM public.tasks x WHERE id=t.id),'تسوية مصدر المهمة');END IF;END LOOP;RETURN jsonb_build_object('checked_bookings',cnt,'as_of',now());END $$;
CREATE OR REPLACE FUNCTION public.task_source_trigger() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.app_settings;u uuid;b uuid;BEGIN SELECT * INTO s FROM public.app_settings WHERE id=1;IF TG_TABLE_NAME='bookings' AND NEW.status='pending' AND NEW.archived_at IS NULL THEN SELECT owner_user_id INTO u FROM public.opportunities WHERE booking_id=NEW.id AND outcome IS NULL ORDER BY created_at DESC LIMIT 1;IF NOT public.task_staff_active(u) THEN u:=public.task_pick_role('leasing_manager');END IF;PERFORM public._task_upsert('booking-contact:'||NEW.id,'تواصل مع العميل','booking_contact',u,NEW.created_at+make_interval(hours=>s.task_response_hours),'booking',NEW.id);ELSIF TG_TABLE_NAME='opportunities' THEN IF NEW.booking_id IS NOT NULL AND NEW.outcome IS NULL AND public.task_staff_active(NEW.owner_user_id) THEN SELECT id INTO b FROM public.bookings WHERE id=NEW.booking_id AND status='pending';IF b IS NOT NULL THEN PERFORM public._task_upsert('booking-contact:'||b,'تواصل مع العميل','booking_contact',NEW.owner_user_id,(SELECT created_at+make_interval(hours=>s.task_response_hours) FROM public.bookings WHERE id=b),'booking',b);END IF;END IF;IF TG_OP='UPDATE' AND (OLD.next_action_at IS DISTINCT FROM NEW.next_action_at OR OLD.outcome IS DISTINCT FROM NEW.outcome OR OLD.stage IS DISTINCT FROM NEW.stage) THEN UPDATE public.tasks SET status='done',completed_at=now(),outcome_note='تم تحديث المتابعة من سجل الفرصة',updated_at=now() WHERE entity_type='opportunity' AND entity_id=NEW.id AND type='opportunity_followup' AND status='open';END IF;IF NEW.outcome IS NULL AND NEW.stage<>'won' AND NEW.next_action_at IS NULL THEN u:=NEW.owner_user_id;IF NOT public.task_staff_active(u) THEN u:=public.task_pick_role('leasing_manager');END IF;PERFORM public._task_upsert('opportunity-followup:'||NEW.id||':missing','متابعة الفرصة','opportunity_followup',u,NEW.created_at+make_interval(hours=>s.task_response_hours),'opportunity',NEW.id);END IF;END IF;RETURN NEW;END $$;
CREATE OR REPLACE TRIGGER booking_task_source AFTER INSERT OR UPDATE ON public.bookings FOR EACH ROW EXECUTE FUNCTION public.task_source_trigger();CREATE OR REPLACE TRIGGER opportunity_task_source AFTER INSERT OR UPDATE ON public.opportunities FOR EACH ROW EXECUTE FUNCTION public.task_source_trigger();
CREATE OR REPLACE FUNCTION public.task_change_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND OLD.status IS DISTINCT FROM NEW.status THEN PERFORM public._safety_audit('TASK_TRANSITION','tasks',NEW.id::text,to_jsonb(OLD),to_jsonb(NEW),coalesce(NEW.outcome_note,'تحديث المهمة'));END IF;RETURN NEW;END $$;CREATE OR REPLACE TRIGGER task_change_audit AFTER UPDATE ON public.tasks FOR EACH ROW EXECUTE FUNCTION public.task_change_audit();
REVOKE ALL ON FUNCTION public.task_pick_role(text),public._task_upsert(text,text,text,uuid,timestamptz,text,uuid,text),public.task_notification_trigger(),public.task_source_trigger(),public.task_change_audit(),public.generate_time_tasks() FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.generate_time_tasks() TO authenticated,service_role;
SELECT to_regprocedure('public.generate_time_tasks()') IS NOT NULL AS generator_ready;